import { PLAYLIST_TRANSITION_HELP } from "../help-text.js";
import { DOCUMENT_LINK_HELP } from "./guidance-text.js";

/** Help-only command notes, part 1 of 2 (guidance.ts joins them; each stays a separate module so the release bundle can keep every file within 256 KiB). */
export const GUIDANCE_NOTES_1: Record<string, string> = {
    "project token": "Replaces the current token subset with 1–64 consented projects. Discovery with project list does not grant access. A lost response keeps the rotation request ID for an identical retry.",
    "bi connection create grafana": "Adds a Grafana connection and prints it with data.secret {set, hint}; the token is sealed on the server and never shown again. Read it from --token-file FILE (the file holds only the token) or - for stdin, never an argument. In Grafana: install the Grafana Image Renderer plugin or the remote rendering service (it draws dashboards as images; without it nothing renders), then create a service account with the Viewer role and add a token. --url is Grafana's own address, including https and any path prefix (https://example.com/grafana); the server calls it from the public Internet, so a private, loopback or reserved address is invalid_request (exit 8), and Grafana must answer without redirecting. Run bi connection test next. Connections belong to one project and are not shared. Creating needs Manage access.",
    "bi connection create web": "Adds a web connection: a service account of a site that shows a dashboard behind a sign-in (Salesforce, Looker Studio, Datadog, HubSpot), or the cookies of a signed-in browser. A web view is one page of it, drawn by a browser on the server and shown as an image, like a Grafana view. --login-mode is required: auto fills the sign-in form on --login-url (https, a public host) with --username and the password from --password-file; steps runs --steps FILE, a JSON array of at most 30 steps (goto with url, fill with selector and value, click and wait_for with selector, press with a key such as Enter and an optional selector, wait_ms with ms from 1 to 10000), where a value may hold {{username}}, {{password}} and {{otp}}, which the server fills from the sign-in, so a script never holds the password; none signs nothing in, and pages show with the cookies of --cookies-file. --cookies-file is a jar exported from a signed-in browser: a cookie extension's JSON array or Playwright's storage state, at most 100 cookies; only name, value, domain, path, expires, httpOnly, secure and sameSite are sent. --totp-file is the base32 key the site shows for the account's authenticator app (or its otpauth://totp address): the server computes the one-time codes a site asks for. The password is typed only into --login-url and the script's goto steps, never into a view's address. The password, key and cookies are sealed and never shown again: data.secret and data.totp_secret say whether they are set, and data.session says where the sign-in stands (idle, active, login_needed, paused, stopped or expired). Use a read-only service account. To protect the account a refused sign-in waits 5 minutes, then 15, 60 and 120, and the fifth in a row stops the connection until its credentials or sign-in settings change. Sites that approve a sign-in on a phone, check devices or show a CAPTCHA cannot be scripted: use a cookie jar. Run bi connection test next, then bi view create --connection-id ID --url PAGE. A server without the page renderer answers bi_web_unavailable (exit 5). Creating needs Manage access.",
    "bi connection create tableau": "Adds a Tableau connection: a connected app (direct trust) of your Tableau Server or Tableau Cloud site, and the Tableau user the screens' views are shown as. The app's secret value is sealed on the server and never shown again; data.secret is {set, hint}. Read it from --secret-file FILE (the file holds only the secret VALUE, not the secret ID) or - for stdin, never an argument. Setup, once: (1) in Tableau, Settings > Connected Apps > New Connected App > Direct trust; (2) copy its Client ID, generate a secret and copy the Secret ID and the secret value; enable the app and the secret; (3) pick or create the Tableau user the screens show, and give it access to only the views screens show: anyone who holds a screen's ticket can embed any view that user can see; (4) run bi connection show ID and enter its embed_origin's host in the connected app's domain allowlist (Only specific domains; Tableau also accepts it with a leading https://). --url is the https address of Tableau Server or of your Tableau Cloud pod (https://10ay.online.tableau.com: the pod, not online.tableau.com) and --site the site's content URL, the part after /site/ or /t/ in a view's address; omit --site for Tableau Server's default site. Tableau Cloud, or Tableau Server 2023.3 or later; the screens must reach the Tableau host, and their browser must accept third-party cookies from it. Run bi connection test next, then bi connection browse to find a view. Connections belong to one project and are not shared. Creating needs Manage access.",
    "bi connection create powerbi": "Adds a Power BI connection: a Microsoft Entra app registration (service principal) and its client secret, sealed on the server and never shown again; data.secret is {set, hint}. Read the secret from --secret-file FILE (the file holds only the secret VALUE, not the secret ID) or - for stdin, never an argument. Setup, once: (1) in Microsoft Entra create an app registration (single tenant, no redirect URI, no API permissions) and a client secret; (2) a Power BI admin turns on, in the admin portal under Tenant settings > Developer settings, Embed content in apps and Service principals can call Fabric public APIs (called Allow service principals to use Power BI APIs or Service principals can use Fabric APIs in older portals), for the whole organization or for a security group that holds the app; (3) add the app to each workspace you will show, with workspace role Member or Admin (the only roles Microsoft documents for an app that embeds; add it as a Member for least access); (4) the workspace must sit on a Fabric (F), Power BI Embedded (A) or Premium (P/EM) capacity for production embedding. Commercial cloud only. --tenant-id is the Directory (tenant) ID or the tenant's domain, not common, organizations or consumers. Instead of --tenant-id, --client-id and --secret-file, --connection-id pcn_... signs in through a Microsoft connection of this project in mode own_app (screenrig connection create microsoft --mode own_app), which holds the app and its secret once; a screenrig_app connection is refused, because Microsoft does not document an application of another tenant as one that can generate embed tokens in a customer's tenant. Run bi connection test next, then bi connection browse to find a workspace and a report. Connections belong to one project and are not shared. Creating needs Manage access.",
    "bi connection list": "Returns data.items, every connection of the project, with secret {set, hint} and the last test. No secret is returned. Read only access is enough.",
    "bi connection show": "Returns one connection: kind, config (url and org_id for Grafana; tenant_id and client_id for Power BI; url, site, client_id, secret_id and username for Tableau), secret {set, hint}, embed_origin (the project's embed host, which a connected app's domain allowlist names) and last_test. Read only access is enough.",
    "bi connection test": "Tableau: signs in as the connection's user with a content-read token signed with the connected app's secret (signin: Tableau's own words when it refuses, such as an unknown secret ID, a disabled app or a user it does not know; a missing REST API at the address names the pod form) and signs out again. It does not judge the domain allowlist (only a screen loading a view proves it) or any view's permissions: bi view test looks the view up as the user. Power BI: asks Microsoft Entra for a token with the app's secret (token) and lists the workspaces the app can see (workspaces: it counts them; none is a failed check that names the workspace step, and a 401 or 403 names the Developer tenant settings and the app's Member or Admin role in the workspace); an AADSTS code from Entra is shown as it is. It does not judge capacity, row-level security or access to any one report: bi view test generates a real embed token. Grafana: calls Grafana with the token and stores the answer as last_test: token (GET /api/search accepts it) and image_renderer (the plugin is listed). A Grafana without the plugin listed only warns, because a remote rendering service does not show as a plugin. It does not judge a dashboard's permissions, data sources or a remote renderer's reachability: bi view test renders for real. A refused token is a failed check with Grafana's answer. Needs Manage access.",
    "bi connection update": "Changes the name, address, organization or token (--token-file replaces the stored one; an omitted token is kept), or for Power BI the tenant, app (--tenant-id, --client-id) or client secret (--secret-file), or for Tableau the site (--site, or --default-site for Tableau Server's default site), connected app (--client-id, --secret-id), user (--username) or secret value (--secret-file). A new address on another host, scheme or port needs --token-file (Grafana) or --secret-file (Tableau) in the same command: the stored secret is only sent to the address it was saved for. For a web connection --login-mode, --login-url, --username and --steps (it replaces the script) change the sign-in, --password-file or --clear-password, --totp-file or --clear-totp, and --cookies-file (it replaces the jar) or --clear-cookies change what is stored, and an omitted secret is kept; a new --login-url on another origin needs --password-file in the same command, and a change of credentials or sign-in settings lifts a stopped session. A new address, organization, tenant, app, site, user or secret clears last_test and retires every render cached for the connection's views; test it again. --expect-rev guards the revision (revision_conflict, exit 6). Needs Manage access.",
    "bi connection browse": "Tableau: lists the views the connection's user can see (data.items of path, as Workbook/View, and name; --query keeps views whose name or path contains it, ignoring case); use a path with bi view create --view. Power BI: lists the workspaces the app can see (data.items of id and name), or with --workspace ID that workspace's reports (id, name, embed_url; --query keeps names containing it); use both ids with bi view create --workspace and --report. Grafana: lists what the token can show, so you can pick a dashboard: data.items of uid, title, folder and tags (--query searches titles; every page is read), or with --dashboard UID the panels of that dashboard (id, title, type; rows are flattened, so a panel inside a collapsed row is listed). Use the uid with bi view create --dashboard, and a panel id with --panel. Read only access is enough.",
    "bi connection delete": "Deletes a connection no view uses. While views use it the answer is resource_conflict (exit 5) naming them; delete those first. --expect-rev guards the revision (revision_conflict, exit 6). Needs Manage access.",
    "bi view create": "Web: give --connection-id of a web connection with --url, the page's https address on a public host (no target flags); --refresh is 60s to 24h and --fit contain|cover|fill applies. --wait-for CSS names an element that shows only when the page is ready and signed in: the capture waits for it and fails with bi_web_timeout when it never shows, so a sign-in page is never drawn. --wait-ms N (0 to 10000) waits a little longer for late charts and --clip CSS draws only that part of the page. A capture happens only while a screen's manifest names the view; the image is shared by every screen of the same size for --refresh and the last good one stays on glass when a capture fails, with status.last_error saying why (bi_web_login_failed, bi_web_otp_required, bi_web_session_expired, bi_web_login_paused, bi_web_timeout, bi_web_navigation_failed or bi_web_blocked). Tableau: give --connection-id with --url (a view address copied from Tableau: https://HOST/t/SITE/views/WORKBOOK/VIEW, Tableau Cloud's https://HOST/#/site/SITE/views/WORKBOOK/VIEW, or just WORKBOOK/VIEW) or --view WORKBOOK/VIEW (from bi connection browse); the address must be on the connection's host and site. --rotate-sheets with --rotate (10s to 1h) turns the workbook's published sheets (each needs the other); --refresh is 60s to 24h (default 5m) or 0 for none; --fit does not apply. The page embeds the view with the Tableau Embedding API: the server signs a five-minute token with the connected app's secret (embed scope only), the page asks for a fresh one when it rebuilds, and the screen never holds the secret. A Tableau Public viz (--public-url https://public.tableau.com/app/profile/USER/viz/WORKBOOK/VIEW, or its /views/ address) needs no connection and no token; --rotate-sheets works there too. The screens must reach the Tableau host and accept its third-party cookies, and the view's embed_origin must be in the connected app's domain allowlist. Power BI: give --connection-id with --url (a report address copied from Power BI, https://app.powerbi.com/groups/WORKSPACE/reports/REPORT, with an optional /ReportSection page) or --workspace and --report (ids from bi connection browse); --page NAME (repeatable, a page name or display name) picks the pages, --all-pages every visible page, and --rotate DURATION (10s to 1h) turns them: two or more pages need --rotate, and --rotate needs two or more pages or --all-pages. --refresh is 60s to 24h (default 5m) or 0 for a DirectQuery or automatic-page-refresh report that updates itself. The page embeds the report with a view-only token the server generates (App owns data), renews it before it expires and never holds the client secret; --fit does not apply. A Publish to web link (--public-url https://app.powerbi.com/view?r=...) needs no connection and shows the report to anyone with the link: it plays as Power BI serves it, reloaded every --refresh, without page rotation. Grafana: Adds a view and prints it with data.embed_url: put that URL in an iframe primitive (content_fit fill; the playlist then holds no credential) and publish as usual. Give --connection-id with exactly one of --url (a dashboard address on the connection's Grafana host; its orgId, viewPanel or panelId, from, to, var-* and theme are read from it) or --dashboard UID (with --panel, --from, --to, --var NAME=VALUE repeatable, --theme dark|light and --timezone), or --public-url alone for a Grafana public dashboard link. A connection view is drawn on the server through Grafana's /render API every --refresh (30s to 24h, default 5m) and shared by every screen of the same size, so ten lobby screens make one render; the screen never talks to Grafana, and keeps the last image, with the render's time in a corner, while Grafana is down. --fit contain|cover|fill sets how the image fills the screen. A public dashboard link plays live from Grafana, which must allow embedding (allow_embedding = true in its settings): bi view test checks it. A view plays only on screens of its own project: the screen's manifest carries the ticket that opens its page, so another project's playlist shows forbidden. Run bi view test next. Creating needs Manage access.",
    "bi view list": "Returns data.items, every view of the project, with its target, cadence, status and embed_url. Read only access is enough.",
    "bi view show": "Returns one view: connection_id, target (view and rotate_sheets for Tableau), refresh_s, rotate_s, fit, status {last_ok_at, last_error {code, detail}} (how it last fared on glass: bi_upstream_refused when Grafana refused the token, bi_upstream_unavailable when it could not render) and embed_url. embed_url is null where this server has no embed host. Read only access is enough.",
    "bi view update": "Changes the name, cadence or fit, or the target: --url, --dashboard, --workspace and --public-url replace the whole target, while --panel, --from, --to, --var, --theme and --timezone change the view's current Grafana one (--var sets one variable and keeps the others) and --report, --page, --all-pages the Power BI one (--page replaces the page list; to clear it give --workspace and --report again with --rotate 0), and --view and --rotate-sheets the Tableau one (--rotate 0 alone stops a Tableau view from turning its sheets). On a web view --url changes the page, and --wait-for, --wait-ms and --clip change how it is drawn (--clear-wait-for and --clear-clip remove those, --wait-ms 0 removes the wait). A new target clears status and retires its cached renders; screens pick the change up at their next refresh without a republish. --expect-rev guards the revision (revision_conflict, exit 6). A view keeps its connection and kind. Needs Manage access.",
    "bi view test": "Tableau connection view: signs in as the connection's user and looks the view up (signin, view); a view the user cannot see, or a name with the wrong case, is a failed view check naming the path. It does not judge the domain allowlist, the embed permission or what the view shows. A Tableau Public view asks Tableau Public whether the workbook exists and does not judge the view name. Power BI connection view: reads the report (report) and generates a real view-only embed token for it (embed_token); Power BI's own reason is shown when it refuses, such as a dataset with row-level security, a 401 or 403 (tenant setting or workspace role) or a report the app cannot see. It does not judge the pages the view names, capacity or what the report shows. A Publish to web link is fetched and its framing headers read. Grafana: renders a connection view for real at 1920x1080, outside the shared cache and without touching the view's status, and answers the checks: data.ok is false with Grafana's reason when it refuses the token, has no renderer or does not know the dashboard (a failed test is data, exit 0). --output FILE saves the PNG instead of running the checks (--width and --height set its size): open it and look before publishing. For a public link it fetches the page and checks that Grafana lets the view's embed page frame it. It does not judge what the picture shows. Needs Manage access.",
    "bi view delete": "Deletes the view. A screen still showing its embed_url answers not_found until its playlist changes. --expect-rev guards the revision (revision_conflict, exit 6). Needs Manage access.",
    "card create": "Creates one instance in the selected project and returns its crd_ ID. Rerun an identical request after a lost response to reuse the saved idempotency key.",
    "card params": "Replaces the instance's static params immediately. Read the instance with card show to check the result.",
    "card data put": "Use --ttl 30m or --expires-at ISO to blank stale data even offline. A replacement without either clears the old expiry. Replaces dynamic data immediately without republishing. Use the revision from card data get with --expect-rev. Read and reconcile after a revision conflict; rerun an identical request after a lost response to reuse the saved key.",
    "card delete": "Deletes one instance; the server refuses while a playlist uses it.",
    "cards list": "Reads the card catalogue. --tag and --category filter it locally, with both filters combined; list one category rather than the whole catalogue. Cards are non-interactive live displays drawn natively on every Player; use an application for touch or other input, a peripheral, an outside system that pushes data itself, or an exact look no card has.",
    "cards show": "Returns params_schema and data_schema unchanged, plus properties.static and properties.dynamic with types, defaults, required flags and limits. Copy example into a playlist page's primitives; replace sample content for the target screen. Place the card with layout (full, free, center, wide, header, footer, corner, chip or strip) from the card's layouts, and anchor for corner, chip (a corner) and strip (an edge); header and footer are full-width bars along the top and bottom edges and take no anchor. The server derives rect and layer for every layout except free. A core card takes the layouts it lists (header and footer only on a card made for them), a fullscreen card full only. A page holds one full, center or wide card, one header, one footer, one corner or chip card per corner and one strip per edge. Set params.theme to a schema-listed theme. A bound data key takes dynamic properties out of params. The example is a placement, not a complete playlist.",
    "background categories": "Returns data.categories: the categories of the page background catalog, each with its set_count and thumbnail_path. The catalog belongs to the platform and every project reads it; nothing is copied into project media. Read only access is enough.",
    "background sets": "Returns data.sets, every match in catalog order: id, name, category and category_name, style, colors (up to three #RRGGBB), thumbnail_path, landscape_count and portrait_count. --category keeps one category, --search keeps sets whose name, style or category name contain every word, and --orientation keeps sets with at least one image in it. Paths are root-relative; human output shows them as absolute URLs on the API origin.",
    "background show": "A set id returns the set with data.backgrounds, one row per image: id, orientation, layout, label, width, height, bytes, sha256, tone and image_path. A background id (bg_...) returns data.background and its data.set. Images are 1280x720 (landscape) or 720x1280 (portrait): choose the orientation of the page's canvas (portrait when its height is greater than its width). layout is where the decoration sits: bottom-banner, center-column, header-footer, left-half, left-rail, light-frame, periphery-frame, right-half, right-rail and top-banner place it in the named area and leave the rest calm; full-bleed-balanced and full-bleed-soft cover the canvas evenly; a texture set names a colour (mustard, charcoal, white). Put content in the calm area, away from the decoration: on left-half text goes on the right, on top-banner content goes below the banner. tone is the image's overall lightness: light content reads on dark. An unknown id is not_found (exit 4).",
    "background apply": "Sets one page's canvas.background to a catalog image and changes nothing else: it reads the playlist, rewrites that page's background as {type: image, background_id, color} and writes the page (PUT), held to the revision it read, or to --expect-rev. A playlist that changed meanwhile answers revision_conflict (exit 6): read it again and rerun. The image is checked against the catalog first (not_found for an unknown id) and plays from the catalog, so the playlist gains no media. --color is the colour under and around the image, #RRGGBBAA (quote it in a shell): without it the page keeps the colour of an image background it already has, else the set's first colour is used, else #000000FF. Review rules are those of playlist page add: under Propose access, or in a project that requires review, it answers pending_review (ok: true, exit 0) and nothing changes on glass until a person approves. Repeating the command after a lost response writes the same page again; playlist show PLAYLIST confirms it.",
    "background clear": "Replaces one page's image background with a solid colour and changes nothing else: --color, else the colour of the image background it replaces. A page with no image background and no --color is a usage error (exit 2) and nothing is written. The write is a page PUT held to the revision it read, or to --expect-rev, and follows the revision, review and recovery rules of background apply.",
    "feeds get": "One read of data fetched and cached by screenRIG; never calls a third-party provider from the agent. Weather, airquality, alerts and earthquakes require --lat and --lon; earthquakes also accepts --radius-km, --min-magnitude and --hours. Cyclones accepts --basins, and the storms near a place with --lat, --lon and --radius-km together. Rates accepts --base; crypto requires --symbols and accepts --currency; headlines requires --url. Cap reads the CAP alerts that match a place and needs --url (repeatable, up to 5 CAP alert or ATOM/RSS index URLs) or --lat and --lon, which read the public feeds covering the location; --public adds those public feeds to --url sources. Cap also accepts --geocode NAME:VALUE area codes (repeatable, needs --lat and --lon); --min-severity, --max-severity, --min-urgency, --min-certainty; --event and --exclude-event (repeatable, * matches any run of characters); --sender, --status (default Actual), --scope (default Public) and --language (first present wins), all repeatable; --area-unknown hide|show. Tides takes --station (a NOAA station id) or --lat and --lon (the nearest station within 100 km). Launches takes no flag. Drugalerts requires --country (us, ca or gb) and takes --category drug (default) or food; respiratory requires --country (us or gb) and takes --region (a US state, territory or DC by name or postal code, or England or a UKHSA region; the nation without it). Almanac takes, all optional, --country, --language (one On This Day edition, default en), --lat with --lon and --date YYYY-MM-DD. Outdoorsafety requires --lat and --lon and reports an estimated wet bulb globe temperature, never lightning. Departures requires --provider (tfl, entur or digitransit) and --stops (one to four ids, comma-separated). Bikeshare requires --lat and --lon and takes --system (without it the nearest listed system that covers the place). A flag a family does not use is refused before any request. 202 returns state pending, retry_after_seconds and retry_at with exit 0; the CLI does not loop. 200 returns the document including fetchedAt and attribution: show the attribution wherever the data shows. Card placements derive feed keys from static params; do not write feed or feed: keys yourself.",
    "invitations create": "Invites people to this project or buyers to its advertising network. Email delivery does not prove receipt. Email invitations expire after seven days; member links expire after 24 hours. At most 50 invitations may be outstanding per organization. --link is a recovery exception, not a setup step: use it only when a person never used their emailed invitation and later asks for dashboard access. It prints one URL once instead of emailing; a link names no recipient and is not email-bound. Deliver it privately and never store or log it. Retry unchanged input after an ambiguous failure to reuse its saved Idempotency-Key. --kind uploader invites a person who works only in the media folders given with --folder-id and the playlists given with --playlist-id (comma-separated; at least one folder): they upload into those folders (media upload --folder ID) and add, replace and remove pages of those playlists (playlist page add|replace|remove), and nothing else; anything else is outside_upload_scope. Their changes wait for review unless --access manage, which only someone who can approve reviews may grant. An uploader never approves reviews. Inviting the same address again replaces the scope of the invitation; a person who is already a member keeps their role, and the owner makes a member an uploader in the dashboard. --kind member with --screen-folder-id (screen folders, each with every folder inside it) and --screen-id (single screens), comma-separated, limits the person who accepts to those screens: they cannot approve reviews until the owner lets them, and a person who is already a member keeps their row. An uploader is limited to media, a scoped member to screens: the two do not combine. A member limited to screens invites no one (outside_screen_scope, exit 3). The owner changes a member's scope afterwards in the dashboard; the CLI has no command for it.",
    "dashboard reset-sign-in": "Unauthenticated: never enrolls, sends a stored token, or changes stored credentials. The acknowledgment is identical for known and unknown addresses. Sign-in reset instructions expire after one hour. To recover an expired enrollment invitation, use --email with the original enrollment address: while ownership is still pending, this emails a new seven-day enrollment invitation even if that person already joined as an ordinary member. Open the enrollment invitation and accept it with the existing sign-in to complete the ownership claim and become responsible for the enrolled agent; the separate sign-in reset link is only needed to replace a lost sign-in. Requesting recovery alone changes no ownership or passkeys. Ordinary member invitations do not claim enrollment ownership. An unresolved request retains only its retry key and fingerprint in the local write ledger.",
    "agent disconnect": "Revokes only the current project's membership. The global identity, other memberships, credentials and project retry state remain. An ambiguous failure retains the original credential for reconciliation.",
    "agent revoke-identity": "Requires --yes. Revokes the global identity and all memberships. An ambiguous failure retains local credentials; confirmed revocation clears credentials and pending work across every cached project.",
    "project list": "Lists only memberships granted to this identity, grouped by organization. Listing preserves the last-used selection. It needs a sign-in with identity access.",
    "organization list": "Lists organizations visible to the responsible person, including empty ones they administer. Organization names are not unique; use the ID for administration. This grants no project membership. free marks a free Standard organization; plan_required marks one that admits no new screens until a paid plan is attached to it; new_organization_allowed is false once the person holds their free organization, so project create adds projects to an existing one. Library names the organization's Library project (library_project_id in the JSON), when it has one.",
    "organization rename": "Requires a verified responsible person who administers this organization. Renaming grants no project access and updates cached project labels without changing the selected project.",
    "project use": "Lists live memberships and selects a project carried by the current token. Use project token --projects ID,ID to replace the subset with up to 64 consented projects. Retry state stays separate per project. --project-id selects a project for one invocation.",
    "project create": "Creates a named project unique within its organization; the responsible person becomes owner. Defaults to the current project's organization, otherwise the organization the person administers or holds free, most recently used first; with no organization named, the organization holding the owner's verified email domain overrides both. One organization option chooses another. Each plan caps an organization's projects; one more is refused with project_limit_reached, whose required_plan names the plan with room (without it, the user contacts support at https://screenrig.ai/contact). Each person has one free Standard organization, and the server refuses a second with free_organization_limit; add the project to the existing organization instead, or the user asks sales@screenrig.ai about a paid plan. Retry the same input after an ambiguous failure; success adds the new project to this sign-in and selects it.",
    "project move": "Only the owner can move to a destination returned by project moves. The move carries screens and checks the destination payer's limit. Existing charges retain their original payer. After an ambiguous failure, inspect project show and project moves before retrying.",
    "project transfer-owner": "Requires an existing verified project member. After an ambiguous failure, inspect the current owner before retrying.",
    "project delete": "Only the project's owner or an administrator of its organization may delete it: an agent deletes for its responsible person, or alone only the project it enrolled while no person has accepted that enrollment. Requires --yes and the exact name and revision from deletion-preview. The project must hold no plan of its own and have no active screens, wallet obligations or live advertising. The server emails members and retains a tombstone. After an ambiguous failure, inspect project list before retrying.",
    "agent status": "Shows this credential's granted capabilities, distinct from project feature entitlements. A forbidden capability refusal needs a new sign-in whose approver grants that capability (screenrig login); retrying the same credential cannot expand its permissions. When this agent has new project notes or notes due for review, warning notes_waiting names them and screenrig notes; human output prints the same line after the result. It also reports the credential's access (read, propose or manage) and effective_access, the level it acts with now. When effective_access is lower, access_limited_by says why: project (the project requires review for agent changes) or person (the responsible person cannot approve reviews). When the project limits this agent to screen folders and screens, screen_scope lists them (folder_ids, each with every folder inside it, and screen_ids). person_screen_scope is the scope of the person responsible for the agent, and the agent acts only on the screens both allow. Both are absent for an agent of the whole project. Only the project owner sets a scope, in the dashboard (Members and Agents); the CLI has no command for it. Outside the scope every screen, folder, selector or audience is refused with outside_screen_scope (exit 3), whose screen_scope names the scope, and screen list, screen folder list and campaign list show only what the scope allows.",
    "screen pair": "Claims the code the Player shows. --folder ID puts the screen in a screen folder (screen folder list shows the IDs); without it the screen sits at the project root. An agent limited to screen folders must give --folder, and it must be a folder of its scope: the project root and every other folder are outside_screen_scope (exit 3). After an interrupted request, rerun the identical command to reuse the saved Idempotency-Key.",
    "screen provision": "Creates a screen and the one-time browser handoff. --folder ID puts the screen in a screen folder (screen folder list shows the IDs); without it the screen sits at the project root. An agent limited to screen folders must give --folder, and it must be a folder of its scope: the project root and every other folder are outside_screen_scope (exit 3). After an interrupted request, rerun the identical command (the same --name and --folder) to reuse the saved Idempotency-Key.",
    "agent enroll": "Creates a new project and first agent, even when the contact email belongs to another project. Supply --email ADDRESS or --agentid-claim CODE with --organization NAME. --agentid-claim redeems a single-use AgentID sign-in claim code obtained at the API host's /agentid/start; the code is never echoed back, and the server derives the contact address from the verified AgentID owner. An invalid, used, or expired claim names signing in again or --email as the next action; an AgentID that already holds an enrolled agent names screenrig login. Enrollment creates Screens; project create NAME creates another project. When the contact person already holds a free Standard organization, their acceptance moves the project into it, renamed on a name clash; if that move is refused, new screens are refused with organization_plan_required. --organization names its organization; --name names this installation. The server emails the contact address a member invitation for their dashboard login; nothing waits on it, so tell the user and go straight on to pairing and content without creating an invitation link. An already enrolled installation reuses its project; a stored credential the server no longer accepts (retired or ended) is replaced by the new enrollment, and the result says so. --force discards a pending enrollment; joining an existing project is screenrig login. --intent advertising enables advertiser=true/screens=false without changing billing-plan assignment. --setup-code CODE passes the setup code a person copied from the website with its setup prompt (two groups of four letters and digits, case and hyphen ignored, sent as XXXX-XXXX) and works with --email or --agentid-claim; it links the new project to that website visit, grants nothing, and an unknown or expired code never fails enrollment. A pending enrollment keeps its original email or AgentID claim, name, purpose, and setup code.",
    "project capabilities": "Read the plan id that pays for this project, independent advertiser/screens feature flags, feature revision, and the server's effective capability set. plan_features lists every plan feature with enabled and the required_plan that includes it, with the featuresets the account holds; limits states the plan's members, video size and event retention (0 is no plan cap); limits.screens is always 0 because no plan caps screens. A feature that is not enabled is refused with feature_not_in_plan (HTTP 402): credit does not unlock it, so tell the user which plan includes it and continue without it. Never infer permission from a quota, plan name, or command inventory. A route denial still wins over previously read capabilities.",
    "dashboard": "Opens the dashboard origin without minting credentials. If the browser opener fails, the origin is printed. Sign in with a retained person credential.",
    "dashboard open": "Opens the dashboard origin without minting credentials. The origin is printed only if the browser opener fails.",
    "app pack": "Local and unauthenticated. Pack an already-built static directory with a root index.html. app upload packs the directory itself; packing first is optional. Inline <style> and <script> blocks move into _screenrig-inline-* files beside each HTML document, preserving relative CSS resource and module dependency paths; inline event handlers and javascript: URLs are refused with the file and line.",
    "app upload": "Creates a new application and its first immutable release. Packs the built directory and waits for processing by default (120000 ms, polling every 1000 ms). With --no-wait, use operations wait on the returned operation_id before using the release. A transfer to storage that is cut off is sent again, up to 4 times, while its upload URL is valid; if it still fails, run the same command again to resume the same upload.",
    "app update": "Creates a new immutable release for the same application and preserves its K/V. Existing playlists remain pinned to their previous release. Use playlist replace-release to preview and apply an explicit replacement. Wait defaults: 120000 ms, polling every 1000 ms.",
    "app rename": "Changes only the display name, using 1 to 120 Unicode characters after trimming and no controls. Preserves the application ID, immutable releases, K/V data, and playlist references. No directory or upload is required. --expect-rev optionally guards against concurrent changes; a stale revision returns revision_conflict with current_revision. Renaming to the current name leaves the revision unchanged.",
    "app delete": "Deletes the application and every one of its releases; there is no per-release delete. Refused with application_in_use while a screen shows one of its releases: assign those screens other content first. It does not check playlists that pin a release without showing it, so update or delete those too. --expect-rev optionally guards against concurrent changes.",
    "media upload": "Transcodes by default and requires ffmpeg and ffprobe. Audio (WAV, AAC/M4A, OGG, FLAC) becomes a 128 kb/s MP3 for a playlist soundtrack; an MP3 source uploads unchanged. --no-transcode uploads accepted bytes unchanged. Waits for processing by default (120000 ms, polling every 1000 ms). Ready media with the same bytes, file name and tag is returned instead of uploading again (data.reused is true), so rerunning an interrupted upload returns its media ID. data.timing reports milliseconds per stage: prepare (transcode and hash), declare, transfer (the upload itself), commit, and processing (until ready, measured at the polling interval). For multiple files use media upload-batch with a manifest. Under Propose access a new upload waits for review (review_state pending): tag, folder and all selectors of approved playlists play it only after a person approves its media review (reviews list) or a playlist review that uses it. --folder ID (an existing media folder, checked before any work starts) declares the upload into that folder, so the file lands there when it is ready and data.folder_id appears; nothing moves afterwards, and it works with --no-wait. media upload-batch --folder declares every item into the folder the same way. An uploader (an invited person or a service client created with --uploader) must name one of its folders, and its uploads under Propose access wait for review like any other. An image or video may be up to 16383 pixels wide or tall and 67,108,864 pixels (8192 by 8192) in one frame; a larger one is refused with invalid_request. The default transcode fits each edge within 3840 pixels, so upload an ultra-wide LED master such as 9216 by 2160 or 12000 by 540 with --no-transcode. One video upload may be at most the video limit of the project's plan: 500,000,000 bytes (500 MB) on Standard and 1,000,000,000 bytes (1 GB) on every other plan (project capabilities states it as media_video_bytes); a larger video is refused before it is read, so trim it to a shorter clip first. The CLI encodes video at a fixed quality and does not change it, so a long video can still exceed the limit after encoding and is then refused; with --no-transcode the file is uploaded as it is, so the file itself must be within the limit. A transfer to storage that is cut off is sent again, up to 4 times, while its upload URL is valid. If it still fails, the error names the upload's operation_id and the upload is cancelled so it holds no storage (with --idempotency-key it is kept for the rerun); run the same command again.",
    "media upload-batch": "The manifest is {\"items\": [{\"path\": \"./a.png\", \"tag\": \"Lobby\", \"content_type\": \"image/png\"}]}: path is required, tag (1 to 32 letters or digits) and content_type are optional, and no other keys are accepted. Reuse the manifest to resume with automatic private state; --state optionally selects its path. Default concurrency is 4 (range 1–8). Transcodes by default; ffmpeg and ffprobe are required unless --no-transcode is used. Upload polling defaults to 1000 ms.",
    "playlist validate": `Local schema and semantic validation; no authentication required. Iframe src and fallback_src take http or https, any host including the screen's LAN, and user:pass@ credentials, or a pasted <iframe> embed code read for its src; the web Player shows only https pages without credentials, native Players show all of them. The path, query and fragment of src and fallback_src may carry screen tokens ({screen.id}, {screen.name}, {screen.timezone}, {screen.field.NAME}, {screen.location.lat}, {screen.location.lon}, {screen.location.name}, {screen.location.address}), kept as written; a token in the scheme, credentials, host or port, or in a YouTube, document or BI view address, is refused at src. An application primitive checks its params (up to 16, ticket and policy reserved, values up to 512 characters). reload_s is 0 or 60 to 86400 seconds, and navigation_allowlist is 1 to 64 strings of at most 2048 characters. Primitive rects may extend outside the canvas for bleed. Players fit content to the whole rect, then clip to the canvas and viewport, so a contain image in an oversized rect is centered in that rect and can fall outside the canvas; use content_fit cover or fill to fill the visible canvas. Authorization and readiness still require server checks. ${PLAYLIST_TRANSITION_HELP}`,
    "playlist create": "Creates a new remote playlist without assigning screens. Supply a canonical {name, pages} document (plus audio, or the format of a video wall playlist), not an inspection envelope. Display names may repeat; IDs identify playlists. Use playlist init to prepare a document or screen publish to create and assign it. Under Propose access, or in a project that requires review for agent changes, it answers pending_review instead (ok: true, exit 0): data.review carries the review id and its dashboard url, warning pending_review names the url, and data.next is screenrig reviews show ID. Nothing changes on glass until a person approves it; tell them it is waiting, do not repeat the write, and check the decision later. --note explains the change to the person who reviews it. A template is a playlist that declares fields ([{name, label, type: text|media|url, required, max_length?}], at most 16) and reads them as {field.NAME} in a card's params, as an image or video selector media_id (a media field) or as the whole src of an iframe (a url field); every token must name a declared field of the right type and every field must be read. Any primitive may carry locked: true (brand content only an owner or a member who can approve changes; it cannot read a field). A template is never shown on a screen: make a playlist from it with --from-template ID --name NAME --set NAME=VALUE (repeatable; a media field takes a ready media ID; --dry-run checks the values and prints the page count), which copies the pages with the values filled in and checks them like any playlist, or add the built-in Urgent notice template (a headline and a message) with --starter urgent-notice. Change a copy's values with playlist fields. A strip is a playlist drawn over the page along one edge of a display: --format-region header (top), footer (bottom) or side (right edge, full height) with --format-orientation landscape|portrait, the orientation of the display it is made for, sets the file's format (and replaces one it holds). Every page of a strip has the same canvas, its long side at least twice the short one and along the edge (for example 1920x240 for a landscape footer, 240x1080 for a landscape side); it holds image and card pages only, no video, stream, iframe, application or ad slot, and no soundtrack. A strip is never a screen's default, a folder default or a takeover: show it with a schedule entry or a campaign whose covers is its region (screen schedule set, campaign create --covers footer). It draws at its canvas aspect, only on displays of its orientation and while it covers at most half the display. A format change that moves a playlist into or out of a region, or to another region, is resource_conflict (exit 5) while a screen, folder or campaign uses it." + DOCUMENT_LINK_HELP,
    "playlist list": "--library lists the organization Library's playlists instead, read-only: assign them to screens, schedules and stacks, or make a copy with playlist create --from-template; change them only in the Library project.",
    "playlist fields": "Plain, it shows a template's fields and how many playlists were made from it, or a copy's values with the template revision it was built from and whether the template has moved on. --set NAME=VALUE (repeatable) and --clear NAME (an optional field) change a copy's values; every change, and --refresh alone, builds the copy's pages again from the template's current revision, which is how a brand change made to the template reaches existing copies (nothing pushes to them). Values are checked like a create checks them. Approvers and Manage write live; under Propose the change becomes a review (pending_review). An uploader may change values of its playlists with media of its folders. A locked primitive stays as the template has it.",
    "playlist instances": "Lists the playlists made from a template with the template revision each was built from; outdated means the template has a newer revision (playlist fields ID --refresh brings a copy up to date).",
    "playlist page add": "Adds one page without resending the others, at the end or in front of --before. --media MED_ID builds the page: one full-canvas image or video on the playlist's canvas with its first page's transition and no dates unless given; an image advances after --seconds (default 10) and is contained unless --fit cover, a video plays to its end, muted unless --sound plays its audio (the page pauses the playlist soundtrack while it shows). --file adds a page object as written (use - for stdin). --from and --until are the page's own dates, civil times in each screen's timezone: it is shown from --from up to, not including, --until; a date alone for --from means that day at 00:00 and for --until the end of that day. Ended pages stay until someone removes them. Under Propose access, in a project that requires review, or as an uploader member whose changes are reviewed, it answers pending_review (ok: true, exit 0); a later page change of the same playlist joins that review while it is waiting, so successive uploads do not replace each other. A playlist no person approved yet answers playlist_not_approved. An uploader adds only media pages of its own folders to its own playlists; anything else is outside_upload_scope, whose upload_scope lists what it may use.",
    "playlist page replace": "Replaces one page, keeping its place and id. --media MED_ID reads the stored page and changes only its media: an image for an image keeps the canvas, fit, seconds and dates (--seconds and --fit change those), and the write is held to the revision it was read at. An image for a video, or the other way, is rebuilt as a media page on the playlist's canvas that keeps the dates. --sound gives the page's video its audio (alone, it changes only that); a page with sound cannot have an audio_cue. --from or --until changes that bound alone and keeps the rest; --always removes the dates and keeps anything else the project set (switched off, weekly windows, a data condition). --file sends a complete page object. Review and uploader rules are those of playlist page add; an uploader replaces only a media page of its own folders.",
    "playlist page remove": "Removes one page. A playlist keeps one to 100 pages and one ordinary page with no dates, so removing the last undated page is invalid_request. Review and uploader rules are those of playlist page add.",
    "playlist patch": "Changes only name, pages, audio and/or format supplied in a partial file or --name/--clear-audio. Omitted fields are preserved; pages, audio and format replace complete values, audio null removes the soundtrack and format null removes the video wall format. Name-only edits preserve existing content without revalidating its authoring format. Use --expect-rev to guard against intervening edits. Propose access and project review policy return pending_review just like playlist update. A region format is {\"region\": \"header|footer|side\", \"orientation\": \"landscape|portrait\"}; see playlist create for strips.",
    "playlist rename": "The name-only form of playlist patch. Preserves pages, soundtrack and comments; --expect-rev optionally guards the revision. A proposed rename waits for a person's approval.",
    "playlist update": "Replaces the authored document and affects every assigned screen. First use playlist show ID --output FILE; edit that document; optionally supply its revision with --expect-rev. Use --overwrite to replace an authoring file; parent directories are created automatically. Under Propose access, or in a project that requires review for agent changes, it answers pending_review instead (ok: true, exit 0): data.review carries the review id and its dashboard url, warning pending_review names the url, and data.next is screenrig reviews show ID. Nothing changes on glass until a person approves it; tell them it is waiting, do not repeat the write, and check the decision later. --note explains the change to the person who reviews it. playlist show keeps returning the live version, not the proposal. To make or change a strip, give --format-region and --format-orientation with the file (see playlist create)." + DOCUMENT_LINK_HELP,
    "playlist show": "Plain show is an inspection response. --editable returns data.document and revision; --output writes the editable document to a file (--overwrite replaces an existing file; an empty file left by an interrupted run is replaced) and reports the revision on stdout. The file is ready for playlist update as written. When both are supplied, --output takes precedence. Plain show reads the open project notes about the playlist: warning notes_about_resource counts them and names screenrig notes --about ID, and human output lists up to five.",
    "playlist revisions": "Reads one page of the playlist's stored revisions, newest first, at most 50: data.items, each with revision, created_at, change, name, page_count, current and, when known, author, and data.next_cursor. change is created (the first revision), edited (a replace, patch, structure change or applied review), promoted (a copy of the earlier revision restored_from names) or baseline (the revision the playlist held when its revision history began; until its next write the list holds that revision alone). While data.next_cursor is a string, older revisions remain: run the command again with --after set to it; null is the last page. Revisions are kept for as long as the playlist is. Read only access is enough.",
    "playlist revision show": "Reads one revision and the playlist as it stood then: data.revision (the fields playlist revisions lists) and data.playlist (name, pages, soundtrack and format, with revision set to this one). A revision the playlist never had, or one from before its history began, is not_found; playlist revisions lists the revisions that exist. playlist promote makes one current again. Read only access is enough.",
    "playlist promote": "Copies revision N forward as a new current revision (the current revision plus one): its pages, soundtrack and format become the playlist's, the playlist keeps its current name, earlier revisions stay as they were, and every screen showing the playlist updates, as for any playlist write. This publishes live, so it needs a credential that publishes live (Manage access from a person who can approve): a Propose access credential gets forbidden, because its writes are proposed for review and a promote is never proposed, and a playlist no person approved yet gets playlist_not_approved. --expect-rev is required and is the playlist's current revision, not N: read it from playlist show ID or the row marked current in playlist revisions ID. On revision_conflict the playlist changed since you read it: read it again, check that the revision to restore is still the one you want, and repeat with the new current revision as --expect-rev. Pages are resolved again as for a structure change: a selector matches today's media, and media or an application the revision used that is gone or not ready refuses the promote with the problem a write would get. A revision whose content equals the current content changes nothing and answers the current playlist with its revision unchanged. The command returns once the playlist is written and does not wait for Players; screen show reports each screen's manifest_upgrade. An interrupted retry uses the same saved write key.",
    "playlist export": "The output directory must not exist. Bundles image and video media, soundtrack audio and iframe URLs (an address with screen tokens keeps its tokens as written) with their reload_s, fallback_src and navigation_allowlist; dynamic media selectors are snapshotted. Cards, streams and adslot pages stop the export. Applications stop it by default; --skip-applications drops them and empty or application-controlled pages, reports skipped ids, and requires at least one remaining page. For an editable document retaining card and application references in the same project, use playlist show <id> --output playlist.json. Referenced resources stay in that project.",
    "playlist import": "Creates a new playlist by default. Display names may repeat. Updating an existing playlist requires --update and affects all its assigned screens; --expect-rev is optional. Under Propose access, or in a project that requires review for agent changes, it answers pending_review instead (ok: true, exit 0): data.review carries the review id and its dashboard url, warning pending_review names the url, and data.next is screenrig reviews show ID. Nothing changes on glass until a person approves it; tell them it is waiting, do not repeat the write, and check the decision later. --note explains the change to the person who reviews it.",
    "screen publish": "Creates a new playlist and assigns it; does not update an existing playlist by name. Optionally guard against concurrent changes with --expect-rev. Use card preview TYPE --params params.json --data data.json --output card.png to inspect an individual card; card preview --now ISO and --timezone ZONE freeze its clock. Repeat identical input to resume an ambiguous failure. Repeating it after a publish finished reports that publish (data.already_published) while the screen still shows its playlist, and publishes afresh once the screen has moved on; a resume never resends an assignment whose expected revision is stale. After a revision conflict inspect the screen and follow the returned recovery instructions. After assignment it waits, bounded by --timeout (default 120000 ms), until the Player acknowledges the playlist on glass: data.stage is playing and data.playback_verified is true. Otherwise data.stage stays assigned, data.playback.reason says why (screen_offline, playlist_not_effective, playback_failed, playback_pending) and a warning of that code says what to do; rerunning the identical command waits again without creating another playlist. --no-wait returns after assignment. Stage changes go to stderr. A screenshot shows the content itself. Publish targets one screen because its revision guard and assignment readback are per screen; for a fleet, create the playlist once with playlist create, then run screen assign --tag TAG --playlist-id ID. Under Propose access, or in a project that requires review for agent changes, the new playlist and its assignment become reviews: publish returns data.stage pending_review with data.reviews (id, kind, state, url), one pending_review warning per review and data.next naming the playlist review, and does not wait for playback. Nothing changes on glass until a person approves; approving the playlist review can approve the assignment with it. While the reviews wait, the identical command reports them again without writing; once the assignment is approved it verifies playback like any publish, and after a rejection, change request or withdrawal it proposes afresh. --note explains the change to the person who reviews it. Storage failures include a storage_full warning in JSON and human output: tell the user to free up storage on the device running the Player, then retry. A saved assignment does not confirm playback. An iframe page that refuses framing in the Player web app adds an iframe_framing_refused warning naming it, as playlist create, update and patch do; data.playback_verified stays as the Player reported it." + DOCUMENT_LINK_HELP,
    "screen update": "Fields are your own values for a screen, such as a store number or a region: --field NAME=VALUE sets one (repeatable) and leaves the screen's other fields as they are, --unset-field NAME removes one, and --clear-fields removes them all. A name is 1 to 32 lower case letters, digits or underscores, a value 1 to 200 characters, and a screen holds at most 32 fields. --location LAT,LON sets where the screen is, in decimal degrees, and replaces the whole previous location, so repeat --location-name (the short place name a card shows, at most 40 characters) and --address (at most 200 characters) to keep them; --clear-location removes it. Changing fields or location changes the screen's manifest revision, so a screen that shows a playlist picks up the new values. Card placements read them per screen, so one playlist shows each screen's own values: {screen.field.NAME}, {screen.name} and {screen.timezone} fill any text param, \"location\": \"{screen.location}\" fills a card's location in the shape that card takes (latitude and longitude, plus name where the card takes one), and a card data key may carry {screen.field.NAME}, for example menu-{screen.field.store_number}. A screen that lacks a field shows that text empty and the card goes without that data key or location. screen show lists a screen's fields and location; screen list --field and --near find screens by them. On a screen in a protected folder only the playlist changes (it answers pending_review for a second approver, alone with no other member); tags, fields, location, timezone and wall are refused with protected_target (exit 5), and a rename stays live.",
    "screen assign": "Assigns an existing playlist. --expect-rev optionally checks the screen revision. Scheduled playlists require the screen timezone. Use screen update to set timezone and assignment together. For a fleet, create the playlist once with playlist create, then assign it with --tag or several ids; each screen applies its own timezone rule and fails individually. With several screen ids, --tag TAG or --folder ID this is one fleet action with no screen-count cap (one metered action; --tag and --folder select active screens only, and --folder reaches the screen folder and every folder inside it). The CLI follows bounded result pages automatically and waits for control budgets to reset, retaining the same key throughout. The envelope stays ok: true and data carries matched, succeeded, failed, and one results[] entry per screen with status ok or failed and that screen's problem. Exit 0 means every screen succeeded; after a partial failure the exit code is the first failed screen's (for example 4 not_found) and warning fleet_partial_failure is set. No match is exit 0 with warning fleet_no_match. --expect-rev applies to one screen id only. After an interrupted or ambiguous request, rerun the identical command to reuse the saved key and replay finished screens without repeating their side effects; an answered request, including a partial failure, is complete, so only the same --idempotency-key replays it. Under Propose access, or in a project that requires review for agent changes, the change (to one screen or to the whole fleet selection) answers pending_review instead: data.review carries the review id and its dashboard url, warning pending_review names the url and data.next is screenrig reviews show ID. Nothing changes on glass until a person approves it; do not repeat the write. --note explains the change to the person who reviews it. Storage failures include a storage_full warning in JSON and human output: tell the user to free up storage on the device running the Player, then retry. A saved assignment does not confirm playback. On a screen in a protected folder this answers pending_review at every access level: an approver other than you, and other than the person you work for, decides the review (second_approver_required, exit 3, otherwise). Do not repeat the write; reviews show ID reads the decision. A caller limited to screen folders assigns only on screens of its scope, and one who cannot approve reviews is refused with approver_required.",
    "screen list": "--state archived also lists screens archived because their player was reset on the display (device_reset) or a paired browser unpaired itself (device_unpair), or screen replace moved their device onto another screen (replaced); the REASON column shows archive_reason when the server reports it. screen unarchive restores any of them but a replaced one, and re-admits the same display key. A row marked applications unsupported has a player that cannot show the application or web page primitives in its playlist. --tag TAG lists only screens carrying that exact tag, and a TAGS column appears when any listed screen has tags. --folder ID lists only the screens directly in that screen folder (not those of the folders inside it) and --folder root only the screens outside every folder; a FOLDER column appears when any listed screen sits in a folder, and folder_id is on every such screen in data. --field NAME=VALUE (repeatable, each name once) lists only screens whose field holds exactly VALUE, and --near LAT,LON,KM only screens located within KM kilometres of the point; screens with no location are left out, and every filter combines with --state and --tag. FIELDS and LOCATION columns appear when any listed screen has them. An UPGRADE column appears when any listed screen has a manifest upgrade story: the upgrade state (pending, downloading, preparing, activating, retrying, failed, blocked, partial, current) and the playlist-version detail Target v42 · Playing v41 — or Target {name} vX · Playing {name} vX when the playlists differ, so incomparable numbers carry their names (id fallback when the name is unknown). Playing is the last server-acknowledged activation; versions are playlist revisions, never screen serials, and the man_ manifest hashes stay out of the column. The failure code, attempt count, missing page count, retry time (overdue when it has passed), and last report time follow. Storage failures include a storage_full warning in JSON and human output: tell the user to free up storage on the device running the Player, then retry. A saved assignment does not confirm playback.",
    "screen show": "An archived screen shows archive_reason and archived_at when the server reports them: project (an project or dashboard archive), device_reset (the player was reset on the display), or device_unpair (a paired browser unpaired itself). Every archive keeps the display's binding, so screen unarchive re-admits the same key and a display that still holds it resumes with no re-pairing. A display reset on the device may start pairing with a new key; that pairing can appear here as recovery_pending, and screen recover moves this screen to the new key (the screen stays archived until screen unarchive). applications_unsupported means the paired player cannot show application or iframe primitives; its manifest is unchanged and the player skips them. The Manifest upgrade block presents playlist versions: Target v42 · Playing v41 when one playlist is upgrading, Target {name} vX · Playing {name} vX when the playlists differ (so incomparable numbers carry their names; the playlist id is the fallback for an unknown name), and just Target vX when nothing is acknowledged yet. Playing is the last server-acknowledged activation, not proof that every connected session shows it; an unknowable version prints Target: unknown version and is never fabricated from the manifest hash, which appears only on a diagnostics line. state, the failure code's reason, attempt, retry time (overdue when past), missing pages while partial, and the last report time follow. A failed screen schedules no retry; fix the cause and screen reload or reassign. It also reads the open project notes about the screen: warning notes_about_resource counts them and names screenrig notes --about ID, and human output lists up to five. data.health.cpu carries load_1m and cores and, when the Player can measure them, utilization_percent (whole-device CPU busy share, 0 to 100) and app_percent (the Player process's share of total CPU capacity, 0 to 100) over the interval since the previous report; a member the Player did not send is absent. data.wall is the screen's video wall (screen wall set) and data.observation.surfaces lists the displays its Player reports, one per output on a wall, whose ids are the output names screen wall set takes. Storage failures include a storage_full warning in JSON and human output: tell the user to free up storage on the device running the Player, then retry. data.commands lists the screen's recent commands (reboot, reload, clear_cache, restart_app and update), oldest first, each with its state (queued, sent, done, failed, expired, cancelled or superseded) and its expires_at, sent_at and done_at, and source schedule when the screen's reboot schedule issued it (absent for one a person or agent asked for); data.reboot_schedule and data.next_reboot_at are the windows the backend reboots the screen in and the start of the next one (screen reboot-schedule set); a clear_cache, restart_app or update the Player ended also carries its cause (for example cleared, restarted, up_to_date, updated, clear_failed, restart_failed, update_check_failed, download_failed, install_failed or no_update_channel) and a short detail, which human output prints as a CAUSE column and a line under the table; a sent command with no report stays sent; screen command cancel cancels one still queued. data.host.capabilities lists what the Player declares; screen clear-cache, restart-app and update-software reach only a Player that declares clear_cache, restart_app or update. data.suspension is the notice a suspended screen shows instead of its content (screen suspend), with since; data.replaced_by on a screen archived as replaced names the screen its device moved to. data.last_outage is the screen's latest outage (offline_since, back_at, duration_s) and, once the first health report after the screen came back decides it, likely_cause: device_restart (power loss or a reboot), app_crash, app_restart, network or platform (a screenRIG service interruption), with the evidence it rests on. It is absent when unknown, which is also the answer for a report without uptimes or one too close to the outage to tell; it cannot tell power loss from a reboot, nor the screen's own network from its upstream. data.volume is the screen's volume: requested (the latest screen volume request: volume_id, level, muted, set_at) and reported (what the Player reached: level, muted, hardware, reported_at, stale), hardware true being the device's output and false the Player's own gain. A saved assignment does not confirm playback.",
    "screen wall set": "One Player drives two to twelve displays as one wall, so a playlist page spans all of them. --outputs names the displays as the Player reports them: take the ids from data.observation.surfaces in screen show (for example HDMI-A-1), in physical order, left to right then top to bottom. --arrangement row is one row of displays, column one column, and grid rows of --columns displays: --columns is required for grid and refused for row and column, and it must be at least 2 and divide the outputs into at least 2 rows (12 outputs make a grid of 2, 3, 4 or 6 columns). --rotation turns every output clockwise (0 when omitted; 90 and 270 are portrait panels). The set replaces the whole wall, so repeat --rotation and --columns to keep them. Only the Linux Player's kiosk install (cage and wlr-randr) and the Windows Player declare the display.wall capability; any other Player answers wall_unsupported (exit 5) and nothing changes. Author the playlist for the wall's shape: playlist init --screen-id ID writes the matching canvas and format {displays, arrangement, orientation, columns for a grid}. A primitive's displays, such as [2] or [1, 2, 5, 6], name the display numbers it covers (left to right then top to bottom, from 1) and must fill a rectangle of the wall. Assigning a playlist whose format is not the wall's shape is playlist_format_mismatch (exit 5); a playlist without a format plays the same on every display. Once the screen plays a playlist with a matching format, every display shows its number and name for 20 seconds after a change, so you can check the order on glass. --expect-rev optionally checks the screen revision (revision_conflict, exit 6). Propose access cannot change a wall (insufficient_access).",
    "screen wall clear": "Removes the wall. The assigned playlist is not re-checked: if it has a format, the screen's manifest degrades (wall_format_mismatch) and the Player keeps its last good page until you assign a playlist without a format. A screen without a wall answers unchanged. --expect-rev optionally checks the screen revision (revision_conflict, exit 6). Propose access cannot change a wall (insufficient_access).",
    "screen display-idle": "Darkens one screen's glass after --after seconds (30 to 86400) without a touch or key or, when --wake lists presence, anybody in front of it; --wake says what lights it again, touch, presence or touch,presence (presence reads the device's camera on the device, no image leaves it). While dark the Player parks playback and reports display power off; a display schedule or override that holds the panel off wins. --off turns idle-dark off. Only display.idle changes. A Player applies it when screen show lists display_power.idle in host.capabilities; the setting is stored either way, and screen show lists it under Display idle. --expect-rev optionally checks the screen revision (revision_conflict, exit 6). Propose access cannot change it (insufficient_access) and a screen in a protected folder refuses it (protected_target, exit 5).",
    "screen brightness": "auto sets one screen's brightness from the device's light sensor; fixed (the default) keeps the operator's brightness. Only display.brightness changes. A Player applies auto when screen show lists brightness.auto in host.capabilities, which a device declares only with a light sensor; the setting is stored either way, and screen show lists it under Display brightness. --expect-rev optionally checks the screen revision (revision_conflict, exit 6). Propose access cannot change it (insufficient_access) and a screen in a protected folder refuses it (protected_target, exit 5).",
    "screen kiosk-lock": "--on pins one screen's Player to the screen (Android screen pinning: the person at the screen confirms the first time, and the status bar, home and recents are blocked while pinned); --off releases it. The operator settings panel can leave the lock until the next manifest or restart applies it again. A Player applies it when screen show lists kiosk_lock in host.capabilities; the setting is stored either way, and screen show lists Kiosk lock while it is on. --expect-rev optionally checks the screen revision (revision_conflict, exit 6). Propose access cannot change it (insufficient_access).",
    "screen archive": "Archiving removes the screen from the default list and darkens the display, but keeps the display's binding: the player stays connected, never re-pairs, and resumes on screen unarchive. Whoever holds the display's key can still connect while it is archived. To retire hardware for good, leave the screen archived or move the screen to new hardware with screen recover or screen replace, which retire the old key.",
    "screen unarchive": "Restores a screen archived for any reason, including one archived because its player was reset on the display (device_reset) or a paired browser unpaired itself (device_unpair). It re-admits the same display key, so a display that still holds it resumes with no re-pairing. A key retired by a confirmed screen recover stays retired. A screen archived as replaced (screen replace) keeps no key and cannot be restored: screen delete removes it.",
    "screen delete": "Deletes a screen no display key is bound to: one still waiting to pair, or a browser Player paired by cookie. A screen whose display holds a bound key is never deleted and nothing unbinds a display remotely, so delete answers screen_archive_required; archive it instead (screen archive), which darkens it. To pair that display as a new screen, confirm a reset on the Player itself, then claim the code it shows with screen pair; the old screen stays archived. To move the screen to replacement hardware, use screen recover, or screen replace when that hardware is already paired as its own screen. A screen archived as replaced holds no key, so it deletes.",
    "screen reload": "Sends the screen's player one reload request and returns its reload_id, state and expires_at. A screen that is online is sent it at once (state sent); an offline screen holds it queued (state queued) and is sent it when it comes online, for 24 hours by default; --expires-in sets that wait from 60s to 24h, the same for every screen of a fleet. A newer reload supersedes one still queued; screen show lists the screen's commands, and screen command cancel ID COMMAND_ID cancels one still queued. A web player reloads at its next page boundary; a native player reconnects, refetches its manifest, and checks for an update. A player ignores a reload within ten minutes of the last one it acted on. Works on active and archived screens; a screen still waiting to pair answers resource_conflict. The screen revision does not change. Repeat with the same --idempotency-key to get the original reload_id back instead of sending another. With several screen ids, --tag TAG or --folder ID this is one fleet action with no screen-count cap (one metered action; --tag and --folder select active screens only, and --folder reaches the screen folder and every folder inside it). The CLI follows bounded result pages automatically and waits for control budgets to reset, retaining the same key throughout. The envelope stays ok: true and data carries matched, succeeded, failed, and one results[] entry per screen with status ok or failed and that screen's problem. Exit 0 means every screen succeeded; after a partial failure the exit code is the first failed screen's (for example 4 not_found) and warning fleet_partial_failure is set. No match is exit 0 with warning fleet_no_match. --expect-rev applies to one screen id only. After an interrupted or ambiguous request, rerun the identical command to reuse the saved key and replay finished screens without repeating their side effects; an answered request, including a partial failure, is complete, so only the same --idempotency-key replays it.",
    "media download": "Streams the stored bytes, verifies their length and SHA-256 against the media record, then moves them into --output (default: the stored filename in the current directory). Like every download (screen screenshot, playback CSV), an existing file at --output is replaced atomically, only after verification; authored documents (playlist init, playlist show --output) instead refuse an existing file unless --overwrite.",
    "screen screenshot": "Requests, waits for, and downloads a screenshot. An existing file at --output is replaced atomically once the image verifies. Default wait is 35000 ms and polling interval is 500 ms. Stdout reports the saved path, never image bytes. Inspect the downloaded image to assess playback. Every run requests a new capture under a fresh key and never replays a stored answer. --timeout bounds each capture's whole wait; 0 leaves it to the server, which expires an unanswered request after 30 s. The server admits 10 captures per screen, 30 per organization and 30 per address per minute. Network failures, 429 and 5xx answers are retried with backoff (at most 6 retries); a 429's Retry-After is honoured even past the default wait, holds every capture of the invocation, and is reported with retry_after_seconds when retries run out. Retries and waits print progress on stderr in --human mode or on a terminal. Before asking again it reads the screen's status and waits on a capture still in progress rather than replacing it, and when a later request replaces its capture it waits for and returns that newer capture of the same screen. When retries run out, the error carries the server's own code and detail. screenshot_unavailable (exit 5) names its reason: the screen is offline, timed_out, unavailable with unsupported_surface (the page shown contains a surface the Player cannot capture, including a visible third-party iframe in the Browser Player) or capture_failed, or still pending when --timeout ran out. Failed captures include error.display when the Player has reported display health: power, connected, reported_at and stale (after 35 minutes). The detail names reported power; a fresh off or standby report suggests retrying when the display is on. This is the latest report, not proof of what caused capture to fail; keep checking the capture reason and report freshness. With several ids, --tag TAG or --folder ID, captures fan out client-side (screenshots are unbilled) with --concurrency captures in flight (1-8, default 4); --tag captures every matching active screen with no screen-count cap from screen list --tag, one billed request per page of the list, and --folder captures every active screen in the screen folder and the folders inside it, listed folder by folder with screen list --folder; captures are unbilled. Screens the list shows offline are reported as failed without a capture. --output is then a directory (default the current directory, created if missing) and each capture writes <screen_id>.webp. data carries matched, succeeded, failed, and results[] with each saved path or that screen's problem; exit and warnings follow the fleet rule: 0 only when every capture succeeded. --idempotency-key is refused in that form.",
    "kv get": "Returns bytes as data.value_base64, including JSON values. Decode base64 and parse JSON only when data.content_type indicates JSON. kv list omits values.",
    "kv set": "--json-value encodes JSON directly. --file reads a local file or stdin with -; --value-base64 accepts canonical padded base64, including empty bytes. Byte modes default to application/octet-stream; --content-type overrides it. JSON mode also accepts an explicit application/json. Omit --expect-rev to create or overwrite; supply it to reject concurrent changes.",
    "kv webhook create": "With --card and --key-template, the mapped output (or raw posted body without --map) contains a documents array of {fields,document} objects; each fields object fills the key template. Use the same template as the card primitive data to read by screen field. Every document validates before writing; retry partial storage failures with the identical body and Idempotency-Key. With --app-id <key>: prints the webhook with data.url (https://api.<domain>/api/applications/<app>/kv-webhooks/<id>/write) and data.secret (srkw_..., shown only here). Put both in the sending system (Zapier, Make, a point of sale, a cron job): it posts the key's new value to data.url with Authorization: Bearer <secret>, or HTTP Basic with the webhook id as the username and the secret as the password. The raw body (at most 1 MiB) becomes the value and its Content-Type the content_type (application/octet-stream when absent); each post replaces the value, increments the revision, is metered like kv set, and reaches apps through screenrig.kv.onChange. The secret is never accepted in the URL. A sender's Idempotency-Key header deduplicates its retries for 24 hours. A webhook takes at most 120 posts a minute. The key need not exist yet. With --card CARD_ID (no key): the JSON (or application/x-www-form-urlencoded) body, at most 1 MiB, becomes the card's data document, either as the object it is or through --map FILE (a JSON template, - for stdin): a string with {{body.alert.title}} or {{body.items[0].name}} placeholders is text, a string that is exactly one placeholder keeps the value's type, {\"$each\": \"{{body.items}}\", \"$template\": {...}, \"$limit\": 20} maps an array, and $group, $number, $bool and $text shape the rest; a path starts with body or query. The template is checked when saved (invalid_request names the place). Every post is checked as the card's own data: card_data_invalid names the path and nothing is written, and a document equal to the card's current one is answered unchanged (no revision, no event). --signing also requires ScreenRig-Signature: t=<unix seconds>,v1=<hex HMAC-SHA256 of \"<t>.<raw body>\" with data.signing_secret> within five minutes of the server's clock, and prints data.signing_secret once. --verify VENDOR with --verify-secret-file FILE (or - for stdin: the secret the vendor shows, or a generic sender's) lets that vendor post straight to data.url: a post that carries the vendor's valid signature in its own header is accepted without data.secret, which keeps working beside it. The vendor's secret is sealed and read back only as verify.secret {set, hint}. Asana takes no secret: create its webhook with the target data.url and its handshake delivers one (events answer secret_pending until then). generic_hmac needs --verify-header NAME and signs the body, or <timestamp>.<body> with --verify-timestamp-header (Unix seconds, or milliseconds with 13 digits) held within --verify-tolerance seconds (default 300); --verify-encoding is hex (default) or base64. --verify excludes --signing. --handshake answers that vendor's setup challenge at data.url before any credential is asked (Slack's and Asana's come with --verify); it writes nothing, is never billed and shows in the deliveries as outcome handshake. A multipart/form-data body is read too: each text field is body.FIELD and file parts are ignored. A wrong address, a wrong secret, a disabled webhook, a bad signature and a GET all answer the same 404; read the reason with kv webhook deliveries. An accepted post is one billed API request. An application or a card has at most 20 webhooks; the 21st is kv_webhook_limit_reached (exit 5). After an interrupted or ambiguous request, rerun the identical command within 24 hours: it reuses the saved Idempotency-Key and the server returns the same webhook and secrets instead of creating another. Creating a webhook needs Manage access.",
    "kv webhook list": "Returns data.items, oldest first, at most 20. An application's webhooks show their key, url and last_used_at once they have written (recorded at most once a minute); a card's show url, mapping (null when the posted object is the document), enabled, signing and last_used_at. A secret is never listed. Read only and Manage access both list webhooks.",
    "kv webhook rotate-secret": "Replaces the secret and prints the new data.secret once; the old one stops working at once, so posts that still carry it answer 401 (a card webhook: the 404 every refusal shares) until the sending system has the new one. --signing with --card replaces the signing secret instead and prints data.signing_secret once. After an interrupted or ambiguous request, rerun the identical command: it reuses the saved Idempotency-Key, so the server returns the rotation that already happened instead of rotating again. Rotating needs Manage access.",
    "kv webhook delete": "The URL stops working at once. The key (or the card's document) it wrote keeps its value; delete a key with kv delete. Deleting needs Manage access.",
    "kv webhook update": "Changes only what you pass on a card webhook. --key-template replaces the keyed-document template; --clear-key-template restores writing the instance document. --map FILE replaces the template (checked when saved), --clear-map removes it so the posted object is the document, --disable makes every post answer the 404 a wrong secret gets until --enable, --signing turns the signature check on and prints data.signing_secret once (a webhook that already signs keeps its secret; replace it with kv webhook rotate-secret --signing), --no-signing turns it off. --verify VENDOR (with --verify-secret-file and the generic_hmac options, as in create) replaces the vendor verification: without a secret it keeps the stored one when the vendor is the same, so a header or a window can change alone, and a different vendor needs its own secret; --clear-verify removes it and its secret; an Asana verification takes a new handshake only after --clear-verify and --verify asana again. --handshake VENDOR sets the vendor handshake the URL answers and --clear-handshake removes it. After an interrupted or ambiguous request, rerun the identical command: it reuses the saved Idempotency-Key. Changing a webhook needs Manage access.",
    "kv webhook deliveries": "Returns data.items, newest first, at most 100, kept for seven days. Each post to the webhook is one row: at, outcome (written, unchanged, refused, invalid or handshake: a vendor's setup challenge, answered, which wrote nothing and took no rate budget), reason (credentials, signature, signature_missing, signature_invalid, timestamp_missing, timestamp_stale, secret_pending, handshake_invalid, disabled, body, mapping, card_data_invalid, rate_limited, payment_required, internal), detail (a fixed sentence, or the card data path that failed), status, bytes, files (the file parts of a multipart post, which are ignored), revision and request_id. signature is a failed ScreenRig-Signature; signature_missing: verify is set and the post carried neither the secret nor the vendor's header; signature_invalid: the header does not match the body; timestamp_missing: the signature needs a timestamp the post lacked; timestamp_stale: the signature was valid and its timestamp is outside the window; secret_pending: an Asana verification still waits for its handshake; handshake_invalid: a handshake that cannot be answered. No body, header or credential is stored. A post to a wrong address leaves no row. Read only and Manage access both read it.",
    "comment set": "Replaces comments with a JSON value from --json-value or --file, including - for stdin. Last write wins; comments do not take --expect-rev or bump the resource revision.",
    "webhooks create": "url must be https on port 443 (the default) or 8443, and its host must resolve only to public Internet addresses; the server re-checks it before every delivery. A refusal is webhook_url_rejected (exit 8) with the server's reason. An organization has at most 50 notifications across its projects, email and webhook together; the 51st is webhook_limit_reached (exit 5). --event-types takes 1 to 32 exact types (screen.online) or prefixes ending in .* (screen.*). The server generates the secret; data.secret is printed only in this answer, with warning webhook_secret_shown_once. Store it in the receiver's secret store at once. The CLI never saves it in its config, operation log, or write-recovery state. After an interrupted or ambiguous request, rerun the identical command within 24 hours: it reuses the saved Idempotency-Key and the server replays the same answer, secret included. Delivery starts with the first event after webhook.created. Deliveries are metered like listen-stream events; the events that are free on the stream are free here.",
    "webhooks update": "Changes only the fields you pass. A new --url is checked like create (webhook_url_rejected, exit 8). --enable on a disabled webhook clears its failure state and starts at the event that records the change; events from while it was disabled are not replayed. --disable fails pending deliveries with webhook_disabled. --expect-rev guards the revision (revision_conflict, exit 6). The secret is unchanged; use rotate-secret.",
    "webhooks rotate-secret": "Replaces the signing secret. The old secret stops signing at once; at most one attempt already in flight may still arrive signed with it, so accept both briefly. The server generates the secret; data.secret is printed only in this answer, with warning webhook_secret_shown_once. Store it in the receiver's secret store at once. The CLI never saves it in its config, operation log, or write-recovery state. After an interrupted or ambiguous request, rerun the identical command within 24 hours: it reuses the saved Idempotency-Key and the server replays the same answer, secret included.",
    "webhooks test": "Appends a webhook.test event and queues one delivery of it to this webhook only. It works on a disabled webhook, is attempted once without retries, is metered like any delivery, never changes failure state, and is limited to 20 per minute per organization (rate_limited, exit 7). Read the outcome with webhooks deliveries.",
    "webhooks deliveries": "One row per event, newest first; retries update the row. state is pending, succeeded, or failed with last_status and a fixed last_error class, never the receiver's response. Send data.next_cursor back as --before for the next page; null means the end of the log.",
    "notifications create": "Pick exactly one channel. --email sends to RECIPIENTS: owner (whoever owns the project when a notice sends) or the user ids of project members; a user id that is not a member is invalid_request (exit 8), and a recipient who has since left or has no verified address is skipped. --webhook POSTs signed JSON to an https URL on port 443 (the default) or 8443 whose host resolves only to public Internet addresses; a refusal is webhook_url_rejected (exit 8) with the server's reason. --slack takes a Slack incoming webhook URL (hooks.slack.com) and posts a Block Kit card; --teams takes a Teams Workflows webhook URL (the trigger \"When a Teams webhook request is received\"; Office 365 connector URLs are retired and refused) and posts an Adaptive Card; --pagerduty takes an Events API v2 routing key, triggers one incident per outage and screen and resolves it when the screen recovers; --telegram takes a bot token with --telegram-chat, the chat id or @channelname to post to. Each needs --conditions, posts one message per outage and screen and a recovery only after that message went out, and retries a failed post for 24 hours like a webhook. The credential is sealed, never printed back (the notification shows only a masked destination_hint), and a - value reads it from one line of stdin so it stays out of shell history; one that does not fit its channel is notification_destination_rejected (exit 8). --conditions lists the screen state changes it fires on: screen_offline, display_disconnected, running_hot, on_battery (the device has a battery and reports it is unplugged; it clears when the device reports any other power source, and the notice says the screen runs on its battery without naming a cause), storage_full, content_stuck, not_playing (the Player shows an error instead of its content), loop_stalled (no media start has reached ScreenRig for longer than the screen's loop allows although the screen is online with current content), glass_blank and glass_frozen (the screen's screenshots, over a run that covers its loop, were all one flat tone or all the same picture), crashing. Two conditions are about a content campaign, not a screen: reach_dropped (a campaign now reaches fewer screens than when it was last published, after screens left its tag or folder, were archived or deleted) and group_empty (a tag or folder its audience names matches no screen; one notice per empty group, naming it in audience_group). They are project-wide: --tag, --any-tag, --all-tags and --audience never limit them, severity, --min-severity and active hours apply as for any condition (default severity warning), and they open no dashboard alert. --reach-drop-screens N and --reach-drop-percent P (1 to 100) with reach_dropped send a notice only for a drop of at least N screens and at least P percent of the screens the campaign reached when published (a drop must meet both; without them any drop notifies); the notice resolves when the campaign reaches all its published screens again. The notice names the campaign and the numbers or the tag or folder, and links to its schedule. card_data_stale is about a card, not a screen: a data document that an agent, a job or a person wrote to a card with an expiry (card data put --ttl) reached it with no new write to renew it while a screen shows the card, so the card is blank there; the notice names the card, links to a page that places it and says since when its data expired, and it resolves when a write to the card's data lands. A data source's own documents are announced by source_stale instead, a card no screen shows sends nothing, and --tag, --any-tag, --all-tags and --audience never limit it. Size --ttl to the writer's schedule, so a job that stopped is noticed. An email, Slack, Teams, PagerDuty or Telegram notification needs conditions; a webhook needs --conditions or --events. --events takes 1 to 32 exact types (screen.online) or prefixes ending in .* (screen.*), POSTed as the same JSON events list returns. --tag limits conditions to screens carrying any of those tags (default every screen); --any-tag and --all-tags limit them to screens carrying at least one or every one of the tags, and --audience takes a campaign audience rule in JSON (inline, a FILE or - for stdin: all, any, tag, screen_id and folder rules nested up to 3 deep) instead of any of them. --min-severity (info, warning, error) creates no opened notice below that level, and a resolved notice follows its opened one. A condition has the severity error for screen_offline and warning for every other; --severity CONDITION=LEVEL (repeatable) sets another for this notification, and it counts for --min-severity and is the severity every channel shows: email, Slack and Telegram text name it when the notification sets either, Teams and PagerDuty always use it. --active-hours \"Mon-Fri 08:00-22:00\" (repeatable, at most 16 windows) with --timezone ZONE sends opened notices only inside those windows: one that falls due outside them waits for the next window to open and goes out then if its condition still holds, a condition that clears first sends nothing, and --outside-hours drop skips the notice instead (last_error outside_hours). A resolved notice for an opened notice that was sent always goes out, and a test notice ignores severity, hours and audience. --hold is how many minutes a condition must last before it notifies (0 to 1440, default 10); a resolved notice follows when it clears after a notice went out, and crashing is sent at once with no resolved notice. A notice still in its hold is skipped when someone acknowledges or snoozes the screen's alert (alerts ack, alerts snooze) or a mute covers the screen (alerts mute). A webhook notice is JSON {type: alert.opened or alert.resolved, id, notification_id, project_id, condition, screen {id, name}, since, at, event_id, severity} with headers ScreenRig-Webhook-Id and ScreenRig-Event-Id (deduplicate on it). A webhook's server-generated secret is printed only in this answer as data.secret, with warning webhook_secret_shown_once. Store it in the receiver's secret store at once. The CLI never saves it in its config, operation log, or write-recovery state. After an interrupted or ambiguous request, rerun the identical command within 24 hours: it reuses the saved Idempotency-Key and the server replays the same answer, secret included. An organization has at most 50 notifications of every channel together, across its projects; the 51st is notification_limit_reached (exit 5). Notices start with the first event after creation. Creating needs Manage access.",
    "notifications list": "Returns data.items, of every channel, oldest first, at most 20. Secrets are never listed; status is active, failing, or disabled (after 72 hours of continuous failure). A chat or pager notification shows destination_hint, its credential masked to the host and last characters, in the TO column. A Read only credential receives each webhook's url empty with url_redacted true, and human output shows (withheld) in the TO column. SNOOZED_UNTIL, EVENTS, RULES (severity filter, overrides, hours, reach-drop threshold and audience) and UNSUBSCRIBED columns appear when a listed notification has them.",
    "notifications show": "Returns the notification with its revision (use it with --expect-rev), status, reach_drop while a threshold is set, min_severity, severity, active_hours (with outside) and audience while they are set, snoozed_until, failing_since, last_success_at, last_failure_at and, for an email notification, unsubscribed: the people who stopped its email with the link in it. A Read only credential receives a webhook's url empty with url_redacted true.",
    "notifications update": "Changes only the fields you pass. --email, --conditions, --events, --tag, --any-tag, --all-tags and --audience replace the whole set (the screen tags and an audience exclude each other: setting one clears the other, and --all-screens clears both). --min-severity sets the severity filter and --clear-min-severity removes it; --severity CONDITION=LEVEL (repeatable) replaces every override and --clear-severity removes them. --active-hours (repeatable) replaces the windows, with --timezone and --outside-hours hold|drop; either of those alone keeps the notification's current windows, and --clear-active-hours removes the hours. --email applies to an email notification, --url and --events to a webhook, and --destination and --telegram-chat (Telegram only) to a Slack, Teams, PagerDuty or Telegram one; a field of another channel is invalid_request (exit 8). A new --url is checked like create (webhook_url_rejected, exit 8) and a new --destination too (notification_destination_rejected, exit 8); - reads it from one line of stdin. --clear-conditions, --clear-events, --all-screens and --clear-description remove a set or the description; the server keeps an email notification at one condition or more and a webhook at conditions or events. --snooze sends nothing until then, and notices that fall due meanwhile are skipped (snoozed): a duration counts from this computer's clock (at most 29d23h59m), an RFC 3339 instant is sent as given (the server allows at most 30 days ahead), and off ends the snooze. --enable on a disabled notification clears its failure state and starts at the event that records the change; nothing from while it was off is sent. --disable fails pending notices with webhook_disabled. --expect-rev guards the revision (revision_conflict, exit 6). The secret is unchanged; use rotate-secret. Needs Manage access.",
    "notifications delete": "Pending notices fail with webhook_deleted and the delivery log is no longer addressable (its rows expire with event retention). --expect-rev guards the revision (revision_conflict, exit 6). Needs Manage access.",
    "notifications rotate-secret": "Webhook notifications only; any other channel is invalid_request (exit 8). Replaces the signing secret. The old secret stops signing at once; at most one attempt already in flight may still arrive signed with it, so accept both briefly. The server generates the secret; data.secret is printed only in this answer, with warning webhook_secret_shown_once. Store it in the receiver's secret store at once. The CLI never saves it in its config, operation log, or write-recovery state. After an interrupted or ambiguous request, rerun the identical command within 24 hours: it reuses the saved Idempotency-Key and the server replays the same answer, secret included. Needs Manage access.",
    "notifications test": "Appends a notification.test event and queues one delivery of it to this notification only: a webhook receives the event as its body, an email notification sends a short test email to its recipients, a Slack, Teams or Telegram notification posts a test message to its chat, and a PagerDuty one triggers an information event (dedup key screenrig:test:DELIVERY_ID) and resolves it at once, so no incident stays open. It works on a disabled or snoozed notification, is attempted once without retries, never changes failure state, and is limited to 20 per minute per organization (rate_limited, exit 7). Read the outcome with notifications deliveries. Needs Manage access.",
    "notifications resubscribe": "Email notifications only. Every email carries an unsubscribe link for its recipient alone (the List-Unsubscribe button of mail apps, and the footer link); following it stops that notification's email to that person, who stays in the recipients and is listed under unsubscribed in notifications show. resubscribe removes the person from that list, so the next notice mails them again. A person who is not unsubscribed changes nothing. A notification that is not an email notification, or one of another project, is not_found (exit 4). Needs Manage access.",
    "notifications deliveries": "One row per event, and per condition of that event for a screen notice; newest first, retries update the row. state is pending, succeeded, failed or skipped. A failed row has last_status and a fixed last_error class, never the receiver's response. A skipped notice says why in last_error: condition_cleared (the screen left the state before the hold ended), not_opened (no notice was sent to resolve), snoozed, acknowledged (someone acknowledged or snoozed the screen's alert during the hold), muted (a mute covers the screen), outside_hours (the notification's active hours were closed and it drops notices outside them), below_severity (the notice is below min_severity, which was raised after it was queued), planned_reboot (the screen went offline, disconnected its display or crashed while restarting for a reboot the service sent, until it is done or ten minutes after it was sent), no_recipients (no recipient is a member with a verified address who has not unsubscribed), grouped (the screen fell into the condition with others, and one notice on another delivery says them all: group_id names the group), or no_longer_judged (a loop_stalled, glass_blank or glass_frozen condition ended because its check stopped judging the screen, so no recovery was said). A group_empty row carries audience_group (tag:NAME or folder:sfd_ID), the AUDIENCE_GROUP column, and a campaign condition's screen_id and screen_name are the campaign's. A screen notice carries condition, phase (opened or resolved), screen_id, screen_name and since; the notice that said a group of screens (the one that opened it and the one that resolved it) carries group {id, attribute, value, count}, and the GROUP column shows it; an email row carries emailed, how many people the email reached. A Slack, Teams, PagerDuty or Telegram row shows the service's answer as last_status and last_error like a webhook's, and secret_unavailable when its sealed credential cannot be opened. Send data.next_cursor back as --before for the next page; null means the end of the log.",
    "audit list": "Returns data.items newest first, each with actor {kind, id, name}, source, action (resource type and verb, such as screen.update), resource {type, id, name} and changes: [{path, before, after}] where path is a JSON Pointer into the resource and a credential reads (redacted) on both sides. revision links the revision a change produced. data.next_cursor (send it back as --after) is null at the end. seq and hash appear once the entry is chained, within seconds. An update that changed nothing leaves no entry. Needs the project capability; Read only access is enough.",
    "audit show": "Returns one entry with every changed field. The human output prints each path with its before and after.",
    "audit head": "Prints the last chained entry as SEQ:HASH, the retention floor the chain starts from, and how many entries are waiting to be chained. Save the head: audit verify --anchor SEQ:HASH later proves that history was not rewritten or truncated.",
    "audit verify": "Recomputes up to 5000 entries per call from the retention floor (or --from-seq) and reports hash_mismatch, prev_mismatch, gap, head_mismatch, anchor_mismatch or floor_mismatch per entry. Exits 13 when the chain does not verify; data.ok is false and data.problems says where. data.next_seq continues a longer chain. --anchor adds the check against a head you kept.",
    "audit export": "Writes the filtered log to --output (default ./audit-log.FORMAT) through the report renderer: one row per changed field, oldest first, the last 30 days unless --since says otherwise, up to 50000 rows (data.truncated otherwise), with the chain head and retention floor in the file. Answers with its path, bytes and sha256. Needs the project capability.",
    "reports show": "Returns the report as data.columns and data.rows (a folder report's rows carry id, parent_id and depth for the outline, and its first row is the whole project), data.totals and data.notes, or with --format csv, xlsx or pdf writes the same rows to --output (default ./KIND-DAY.FORMAT) and answers with its path, bytes and sha256. A paged report is written whole, up to 50000 rows (data.truncated otherwise). proof_of_play needs a project that sells ad time on its own screens. Read only access with the reports capability is enough.",
    "reports subscriptions create": "Recipients must be members of the project: a user id (members list in the dashboard) or a member's email address. Each run covers the period before it in UTC days. A PDF or XLSX attachment is limited to 8 MiB; a larger report is not mailed and the subscription shows last_status failed. Needs the project capability and Manage access.",
    "reports subscriptions send": "Mails the report now, for the period a run now would cover, and answers with the subscription including this send's last_status and last_error. Its schedule does not move.",
    "project export": "export.json is written last: it lists every file with its size and SHA-256 and each section's outcome (ok, skipped, failed). warning export_section_failed means the copy is incomplete: run the same command again. Original media are verified against the project's recorded SHA-256 before they are kept. The export never contains a webhook signing secret, a receiver URL, a source credential or a fleet link.",
    "alerts list": "Returns data.items, open alerts first and newest first, with data.counts {open, attention} for the whole project whatever the page and filters, and data.next_cursor (null at the end of the list; send it back as --before). --state open is the default; resolved alerts stay for the plan's event retention. Each alert has its screen, condition, since, state, muted and attention, and acknowledged_at, acknowledged_by, snoozed_until or resolved_at where they apply. Human output adds how long each has lasted and its standing: open, acknowledged, snoozed until a time, muted, or resolved. Read only access is enough.",
    "alerts show": "Returns one alert: screen_id and screen_name, condition, state (open or resolved), since, resolved_at, acknowledged_at and acknowledged_by (a person or an agent, with its name), snoozed_until, muted and attention. A resolved alert is found until the plan's event retention ends; after that its id is not_found (exit 4). Read only access is enough.",
    "alerts ack": "Marks an open alert as handled: it stays acknowledged until it resolves and needs no attention meanwhile. The alert records who acknowledged it (a person or an agent) and when. Only an open alert can be acknowledged; a resolved one is alert_not_open (exit 5). While an alert is acknowledged or snoozed, a notification's notice about it that is still in its hold is skipped (skip reason acknowledged in notifications deliveries). A later ack or snooze replaces the earlier one. Needs Manage access.",
    "alerts snooze": "The same acknowledgement with an end: --for counts from this computer's clock (at most 29d23h59m) and --until is an RFC 3339 instant with seconds and an offset (the server allows at most 30 days ahead, else invalid_request, exit 8). The alert needs attention again at that time if it is still open. Only an open alert can be snoozed; a resolved one is alert_not_open (exit 5). A later ack or snooze replaces the earlier one. Needs Manage access.",
    "alerts mute": "Mutes screens for maintenance until the end you give: --screen-id lists screens and --tag covers every screen carrying one of those tags at the time a notice falls due; give both to cover both. --for counts from this computer's clock (at most 29d23h59m) and --until is an RFC 3339 instant with seconds and an offset (the server allows at most 30 days ahead, else invalid_request, exit 8). Their alerts still open and resolve, marked muted, and never need attention, and every notification skips the notices about them (skip reason muted in notifications deliveries). An organization has at most 50 current mutes across its projects; one more is alert_mute_limit_reached (exit 5). A mute ends at its time or sooner with alerts unmute. After an interrupted or ambiguous request, read alerts mutes first: rerunning the identical command with --until within 24 hours reuses the saved Idempotency-Key and the server returns the same mute, while a rerun with --for starts from a new time and makes another. Needs Manage access.",
    "alerts mutes": "Returns data.items: the project's current mutes, soonest end first, at most 50, each with its screen_ids, tags, until, note and who created it. A mute that has ended drops out of the list. Read only access is enough.",
    "alerts unmute": "Ends the mute now. Open alerts on its screens need attention again unless they are acknowledged or snoozed, and notifications stop skipping their notices. A mute that has ended is not_found (exit 4). Needs Manage access.",
    "playback list": "JSON returns data.items, at most 200 daily aggregates (one row per screen, media, and UTC day), newest day first. Aggregates refresh about every 10 minutes, so the newest plays reach this list after that lag; playback plays shows them sooner. --day selects one UTC day; --day-from and --day-to select an inclusive range of at most 366 days. --format csv streams every matching row (by default the 31 days up to today) as one billed request into --output FILE (default ./playback-aggregates.csv), written to a private temp file that replaces an existing FILE only after a complete stream (--timeout is the no-progress limit, default 60000 ms); the envelope reports path, bytes, rows, and sha256, never the CSV. --output - writes the CSV to stdout instead of the envelope. A CSV export spends the playback export budget (30 per minute per organization); past it the answer is rate_limited (exit 7) with retry_after_seconds.",
    "playback plays": "One row per visible start of an image, video or application (application rows carry release_id and an empty media_id), oldest first by received_at. --from and --to bound received_at (inclusive, exclusive) and take RFC 3339 with seconds and an offset (normalized to UTC), now, or an age before now (7d, 12h, 30m); the defaults are the 24 hours up to now, and a range is at most 31 days. The newest 5 seconds are held back until they settle, so a play shows up about 5 seconds after it is received; data.to is the effective end, at most 5 seconds before now, and data.next keeps it. JSON is one page (server default 200 rows, --limit up to 1000) with data.next_cursor; send it back with --cursor and the same filters, or run data.next. --all follows next_cursor (1000 rows per page unless --limit) for at most 50 pages; it stops early with data.next when the playback export budget (30 requests per minute per organization) is spent, with warning playback_export_rate_limited, or at the page cap with warning playback_plays_truncated. Each page is one billed request; --format csv streams the whole range in one billed request into --output FILE (default ./playback-plays.csv) via a private temp file in the same directory that replaces an existing FILE only after a complete stream, and reports path, bytes, rows, sha256, and last_received_at. If the stream fails partway, the export exits non-zero, the target is not written, the complete rows received are kept in FILE.partial (FILE.partial-2 and so on when that exists), and error.next resumes from the last received_at into an unused FILE-rest.csv (rows at that instant repeat). The stream fails after --timeout milliseconds without a byte (default 60000), never on total duration. --output - writes the CSV to stdout instead of the envelope. primitive_id and started_at are empty unless the Player reported them.",
    "playback totals": "Plays over inclusive UTC days from the daily rollups, which follow ingestion by up to about 21 minutes (playback plays shows newer starts). --by day (default) answers data.days, one row per day; --screen-id or --media-id (not both) narrows it to one screen or media. --by screen or media ranks the busiest into data.screens or data.media, and --by screen_day answers data.screen_days, the day series of the top screens; --top sets the count (default 10, at most 100, at most 10 for screen_day) and does not apply to --by day. --day-to defaults to today and --day-from to 29 days before it; a day series spans at most 366 days (92 with --screen-id or --media-id) and a ranking at most 92. data.truncated is true when a ranking over a window too large for one read kept only the best keys of each slice. One metered API request; the playback export budget does not apply.",
    "playback completeness": "How many of the plays Players numbered reached screenRIG, over inclusive UTC days. Each media start carries a number, so a play a screen made and never delivered (offline past its 24-hour report queue, for example) leaves a gap. data.completeness is measured_plays over measured_plays plus missing_plays for the window, and data.days gives the same per UTC day; null means not measured: plays without numbers, from Players that do not number their plays or before they did. A switched-off screen makes no plays and leaves no gap. data.gaps lists each gap newest first: screen_id, day (the UTC day it came to light), from and to (the start times of the plays either side) and missing_plays; --limit caps it (default 100, at most 500) and data.truncated says more exist. --screen-id narrows to one screen. --day-to defaults to today and --day-from to 29 days before it; a window spans at most 92 days. The rollup refreshes every 10 minutes. One metered API request; the playback export budget does not apply.",
};
